import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class Node_hasAttr_TriageGen1Test {

    @Test
    public void testHasAttr_PresentAttribute() {
        Node node = new Element("div");
        node.attributes().put("data-id", "123");
        assertTrue(node.hasAttr("data-id"));
    }

    @Test
    public void testHasAttr_AbsentAttribute() {
        Node node = new Element("div");
        assertFalse(node.hasAttr("data-id"));
    }

    @Test
    public void testHasAttr_NullAttributeKey() {
        Node node = new Element("div");
        assertThrows(NullPointerException.class, () -> node.hasAttr(null));
    }

    @Test
    public void testHasAttr_EmptyStringAttributeKey() {
        Node node = new Element("div");
        assertFalse(node.hasAttr(""));
    }

    @Test
    public void testHasAttr_SingleSpaceAttributeKey() {
        Node node = new Element("div");
        assertFalse(node.hasAttr(" "));
    }

    @Test
    public void testHasAttr_MultipleSpacesAttributeKey() {
        Node node = new Element("div");
        assertFalse(node.hasAttr("   "));
    }

    @Test
    public void testHasAttr_TrimmedAttributeKey() {
        Node node = new Element("div");
        assertFalse(node.hasAttr("   data-id  "));
    }
}
